import {
  BODY_DOCUMENT_ID,
  DocumentDefinition,
  DocumentDefinitionType,
  DocumentType,
  RootElementOption,
} from '../../../models/datamapper/document';
import { PathUtil } from '../../path-util';
import { XmlSchemaAnalysisReport, XmlSchemaAnalysisService } from './xml-schema-analysis.service';
import { XmlSchemaDocumentService } from './xml-schema-document.service';

/** Text that marks a schema as generated by Kaoto. A schema without it is a user file and must never be overwritten. */
export const GENERATED_WRAPPER_MARKER = 'Generated by Kaoto DataMapper';
export const GENERATED_WRAPPER_NOTICE = 'Do not edit';
/** Suffix that is appended to the name of the XSLT file to get the name of its validation wrapper. */
export const VALIDATION_WRAPPER_SUFFIX = '-validation-wrapper';

/**
 * Result of {@link XmlSchemaWrapperGeneratorService.computeValidationUri}.
 * `warnings` lists the reasons for a fallback or a dropped import. They are meant to be reported
 * by the caller (the generator itself does no logging).
 */
export type XmlValidationUri =
  | { kind: 'root'; uri: string; warnings: string[] }
  | {
      kind: 'wrapper';
      uri: string;
      xsd: string;
      /** Generated aggregator schemas the wrapper imports, by path. Empty when no namespace has several files. */
      aggregators: Record<string, string>;
      warnings: string[];
    };

export interface XmlSchemaWrapperInput {
  /** Schema files by path. Its key order is the file order (first key is the fallback root). */
  definitionFiles: Record<string, string>;
  rootElement?: RootElementOption;
}

/**
 * Service that handles dynamic generation of thin XML Schema wrappers
 * for multi-file targets that do not form a single reachable graph.
 *
 * The service is pure: it does no I/O and no logging. The schema graph and its unreferenced schemas are
 * computed by {@link XmlSchemaAnalysisService}.
 */
export class XmlSchemaWrapperGeneratorService {
  /**
   * Computes the filepath where the generated validation wrapper XSD should be stored.
   * The result is never equal to the input, so saving the wrapper can not overwrite the XSLT file,
   * even when the (hand-editable) metadata contains a path that does not end in `.xsl`.
   *
   * @param xsltPath The path to the parent XSLT mapping file.
   * @returns The computed path to the wrapper schema.
   */
  static getWrapperPath(xsltPath: string): string {
    return /\.xsl$/i.test(xsltPath)
      ? xsltPath.replace(/\.xsl$/i, `${VALIDATION_WRAPPER_SUFFIX}.xsd`)
      : `${xsltPath}${VALIDATION_WRAPPER_SUFFIX}.xsd`;
  }

  /**
   * Checks whether the given XSD content was automatically generated by Kaoto.
   *
   * @param xsd The XML Schema content to inspect.
   * @returns True if it is a generated wrapper, false otherwise.
   */
  static isGeneratedWrapper(xsd: string): boolean {
    return xsd.includes(GENERATED_WRAPPER_MARKER) && xsd.includes(GENERATED_WRAPPER_NOTICE);
  }

  /**
   * Computes the validation URI for an XML target body. When multiple unconnected schemas are
   * attached, it generates a thin wrapper XSD pulling them into a single namespace-compliant graph.
   *
   * Falls back to the first (or the single unreferenced) schema file, with a warning, when the schemas
   * cannot be analysed, have no unreferenced schema or the root namespace cannot be determined.
   *
   * XML Schema processors keep one grammar per namespace and read only the first location they meet for it. To
   * not depend on the processor, every file takes part in the wrapper exactly once:
   * - all files of the root namespace are `xs:include`d by the wrapper itself;
   * - every other namespace is `xs:import`ed once. A namespace with several files gets a generated aggregator
   *   schema (see {@link getAggregatorPath}) that `xs:include`s all of them;
   * - the imports come before the includes, and a namespace that other namespaces import comes first, so that the
   *   aggregator, not a file reached through an import chain, claims the namespace.
   *
   * An import cycle between namespaces of which one has several files can not be solved by ordering. It is
   * reported as warning.
   *
   * @param input The multi-file schema content and root element configuration.
   * @param wrapperPath The path where the wrapper XSD should be stored.
   * @param xsltPath The path of the XSLT file the wrapper belongs to; its name is written in the generated comment.
   *   Defaults to the wrapper path.
   * @returns An object describing the validation URI type, any generated content and warnings.
   */
  static computeValidationUri(
    input: XmlSchemaWrapperInput,
    wrapperPath: string,
    xsltPath: string = wrapperPath,
  ): XmlValidationUri {
    const warnings: string[] = [];
    const files = Object.keys(input.definitionFiles);
    if (files.length === 0) {
      return { kind: 'root', uri: '', warnings };
    }
    if (files.length === 1) {
      return { kind: 'root', uri: files[0], warnings };
    }

    const analysis = XmlSchemaAnalysisService.analyze(input.definitionFiles);
    if (analysis.errors.length > 0) {
      warnings.push(
        `Schema analysis failed, validating against "${files[0]}" only: ${analysis.errors.map((e) => e.message).join('; ')}`,
      );
      return { kind: 'root', uri: files[0], warnings };
    }

    const unreferenced = XmlSchemaAnalysisService.findUnreferencedSchemas(analysis);
    if (unreferenced.length === 0) {
      warnings.push(`No unreferenced schema found, validating against "${files[0]}" only`);
      return { kind: 'root', uri: files[0], warnings };
    }
    if (unreferenced.length === 1) {
      return { kind: 'root', uri: unreferenced[0], warnings };
    }

    const rootNamespace = this.determineRootNamespace(input, warnings);
    if (rootNamespace === null) {
      return { kind: 'root', uri: files[0], warnings };
    }

    const { xsd, aggregators } = this.generateXsdWrapper(
      files,
      rootNamespace,
      wrapperPath,
      PathUtil.extractFilename(xsltPath),
      analysis,
      warnings,
    );
    return { kind: 'wrapper', uri: wrapperPath, xsd, aggregators, warnings };
  }

  /**
   * Computes the path of the n-th (1-based) aggregator schema of a wrapper. It lives next to the wrapper.
   */
  static getAggregatorPath(wrapperPath: string, index: number): string {
    return `${wrapperPath.replace(/\.xsd$/i, '')}-${index}.xsd`;
  }

  /**
   * Finds the aggregator schemas a generated wrapper imports.
   *
   * @param wrapperPath The path of the wrapper
   * @param wrapperXsd The content of the wrapper
   * @returns The paths of the aggregators
   */
  static findAggregatorPaths(wrapperPath: string, wrapperXsd: string): string[] {
    const directory = PathUtil.extractDirectory(wrapperPath);
    const name = this.escapeXmlAttr(PathUtil.extractFilename(wrapperPath).replace(/\.xsd$/i, ''));
    // Tolerates a reformatted wrapper: either quote style and whitespace around the `=`
    const pattern = new RegExp(`schemaLocation\\s*=\\s*(["'])(${this.escapeRegExp(name)}-\\d+\\.xsd)\\1`, 'g');
    return Array.from(wrapperXsd.matchAll(pattern), (match) => {
      const location = this.unescapeXmlAttr(match[2]);
      return directory ? `${directory}/${location}` : location;
    });
  }

  /**
   * Rewrites a generated wrapper so that it references the aggregators that belong to another wrapper path.
   * Used when a wrapper is copied next to a new XSLT file; the aggregators move along with it.
   *
   * @param wrapperXsd The content of the wrapper at `oldWrapperPath`
   * @param oldWrapperPath The current wrapper path
   * @param newWrapperPath The new wrapper path
   * @returns The wrapper content for `newWrapperPath`
   */
  static retargetAggregators(wrapperXsd: string, oldWrapperPath: string, newWrapperPath: string): string {
    const oldName = this.escapeXmlAttr(PathUtil.extractFilename(oldWrapperPath).replace(/\.xsd$/i, ''));
    const newName = this.escapeXmlAttr(PathUtil.extractFilename(newWrapperPath).replace(/\.xsd$/i, ''));
    // Tolerates a reformatted wrapper: either quote style and whitespace around the `=`
    const pattern = new RegExp(`(schemaLocation\\s*=\\s*)(["'])${this.escapeRegExp(oldName)}-(\\d+\\.xsd)\\2`, 'g');
    return wrapperXsd.replace(
      pattern,
      (_whole, prefix: string, quote: string, rest: string) => `${prefix}${quote}${newName}-${rest}${quote}`,
    );
  }

  /**
   * Maps the path of an aggregator of `oldWrapperPath` to the path of the matching aggregator of `newWrapperPath`.
   */
  static retargetAggregatorPath(aggregatorPath: string, oldWrapperPath: string, newWrapperPath: string): string {
    const oldBase = oldWrapperPath.replace(/\.xsd$/i, '');
    const newBase = newWrapperPath.replace(/\.xsd$/i, '');
    return `${newBase}${aggregatorPath.slice(oldBase.length)}`;
  }

  private static determineRootNamespace(input: XmlSchemaWrapperInput, warnings: string[]): string | null {
    const docDef = new DocumentDefinition(
      DocumentType.TARGET_BODY,
      DocumentDefinitionType.XML_SCHEMA,
      BODY_DOCUMENT_ID,
      input.definitionFiles,
      input.rootElement,
    );

    const firstFile = Object.keys(input.definitionFiles)[0];
    try {
      const docResult = XmlSchemaDocumentService.createXmlSchemaDocument(docDef);
      const rootElement = docResult.document?.rootElement;
      if (docResult.validationStatus === 'error' || !rootElement) {
        warnings.push(`Failed to determine the root element, validating against "${firstFile}" only`);
        return null;
      }
      return rootElement.getQName()?.getNamespaceURI() || '';
    } catch (err) {
      warnings.push(`Error while determining the root element, validating against "${firstFile}" only: ${err}`);
      return null;
    }
  }

  private static generateXsdWrapper(
    files: string[],
    rootNamespace: string,
    wrapperPath: string,
    xsltName: string,
    analysis: XmlSchemaAnalysisReport,
    warnings: string[],
  ): { xsd: string; aggregators: Record<string, string> } {
    const sanitizedXsltName = xsltName.replace(/-+/g, '-');
    const firstComment = `<!-- ${GENERATED_WRAPPER_MARKER} for ${sanitizedXsltName}. ${GENERATED_WRAPPER_NOTICE}; it is regenerated. -->`;
    const header = `<?xml version="1.0" encoding="UTF-8"?>\n${firstComment}\n`;

    // A chameleon schema (no targetNamespace) that another file includes takes the namespace of that file.
    // It must not additionally be loaded as a no-namespace schema.
    const chameleonIncludes = new Set(
      analysis.edges
        .filter((edge) => edge.directive.type === 'include' && !analysis.fileInfos.get(edge.to)?.targetNamespace)
        .map((edge) => edge.to),
    );

    const filesByNamespace = new Map<string, string[]>();
    for (const file of files.filter((f) => !chameleonIncludes.has(f))) {
      const namespace = analysis.fileInfos.get(file)?.targetNamespace || '';
      filesByNamespace.set(namespace, [...(filesByNamespace.get(namespace) ?? []), file]);
    }

    const includeOf = (file: string) =>
      `<xs:include schemaLocation="${this.escapeXmlAttr(PathUtil.relativePath(wrapperPath, file))}"/>`;

    const aggregators: Record<string, string> = {};
    const imports: string[] = [];
    const importNamespaces = this.orderImportedNamespaces(filesByNamespace, rootNamespace, analysis, warnings);
    for (const namespace of importNamespaces) {
      const namespaceFiles = filesByNamespace.get(namespace) ?? [];
      const namespaceAttr = namespace === '' ? '' : ` namespace="${this.escapeXmlAttr(namespace)}"`;
      let location: string;
      if (namespaceFiles.length === 1) {
        location = PathUtil.relativePath(wrapperPath, namespaceFiles[0]);
      } else {
        const aggregatorPath = this.getAggregatorPath(wrapperPath, Object.keys(aggregators).length + 1);
        const targetAttr = namespace === '' ? '' : ` targetNamespace="${this.escapeXmlAttr(namespace)}"`;
        aggregators[aggregatorPath] =
          `${header}<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema"${targetAttr}>\n` +
          `${namespaceFiles.map((file) => `  ${includeOf(file)}`).join('\n')}\n</xs:schema>\n`;
        location = PathUtil.relativePath(wrapperPath, aggregatorPath);
      }
      imports.push(`<xs:import${namespaceAttr} schemaLocation="${this.escapeXmlAttr(location)}"/>`);
    }

    const includes = (filesByNamespace.get(rootNamespace) ?? []).map(includeOf);

    let schemaTag = `<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema"`;
    if (rootNamespace !== '') {
      schemaTag += ` targetNamespace="${this.escapeXmlAttr(rootNamespace)}"`;
    }
    schemaTag += '>';

    const directives = [...imports, ...includes];
    const xsd = `${header}${schemaTag}\n${directives.map((d) => `  ${d}`).join('\n')}\n</xs:schema>\n`;
    return { xsd, aggregators };
  }

  /**
   * Orders the namespaces the wrapper imports (every namespace but the root one). A namespace that another
   * one imports (or includes from) comes before the importing one. Cycles keep the input order and are reported
   * when a namespace of the cycle has several files, since an aggregator can not claim its namespace first then.
   */
  private static orderImportedNamespaces(
    filesByNamespace: Map<string, string[]>,
    rootNamespace: string,
    analysis: XmlSchemaAnalysisReport,
    warnings: string[],
  ): string[] {
    const namespaceOf = (file: string) => analysis.fileInfos.get(file)?.targetNamespace || '';
    const dependencies = new Map<string, Set<string>>();
    for (const namespace of filesByNamespace.keys()) {
      dependencies.set(namespace, new Set());
    }
    for (const edge of analysis.edges) {
      const from = namespaceOf(edge.from);
      const to = namespaceOf(edge.to);
      if (from !== to) dependencies.get(from)?.add(to);
    }

    const ordered: string[] = [];
    const state = new Map<string, 'visiting' | 'done'>();
    const visit = (namespace: string) => {
      if (state.get(namespace) === 'done') return;
      state.set(namespace, 'visiting');
      for (const dependency of dependencies.get(namespace) ?? []) {
        if (state.get(dependency) === 'visiting') {
          if (
            (filesByNamespace.get(namespace)?.length ?? 0) > 1 ||
            (filesByNamespace.get(dependency)?.length ?? 0) > 1
          ) {
            warnings.push(
              `Namespaces "${namespace}" and "${dependency}" are part of an import cycle and one of them has several schema files, validation may not load all of them`,
            );
          }
        } else {
          visit(dependency);
        }
      }
      state.set(namespace, 'done');
      ordered.push(namespace);
    };
    for (const namespace of filesByNamespace.keys()) {
      visit(namespace);
    }
    // A chameleon include can add a namespace without files of its own to the edges; there is nothing to import
    return ordered.filter((namespace) => namespace !== rootNamespace && filesByNamespace.has(namespace));
  }

  private static escapeRegExp(val: string): string {
    return val.replace(/[.*+?^${}()|[\]\\]/g, String.raw`\$&`);
  }

  private static unescapeXmlAttr(val: string): string {
    return val
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&gt;/g, '>')
      .replace(/&lt;/g, '<')
      .replace(/&amp;/g, '&');
  }

  private static escapeXmlAttr(val: string): string {
    return val
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&apos;');
  }
}
